export function turnInputFromComposer(
  text: string,
  mentions: ComposerMentionInput[] = [],
): UserInput[] {
  return [
    { type: "text", text, text_elements: [] },
    ...mentions.map((mention) =>
      mention.kind === "skill"
        ? ({
            type: "skill" as const,
            name: mention.name,
            path: mention.path,
          } satisfies UserInput)
        : ({
            type: "mention" as const,
            name: mention.name,
            path: mention.path,
          } satisfies UserInput),
    ),
  ];
}

