  selectedThread: Thread | null;
  selectedThreadId: string | null;
  serverUrl: string;
  setAccountStatus: (accountStatus: AccountStatus | null) => void;
  setConnectionAttempt: (updater: (attempt: number) => number) => void;
  setConnectionState: (state: ConnectionState) => void;
  setConversationSummary: (summary: ConversationSummary | null) => void;
  setGitRemoteDiff: (diff: GitRemoteDiffSummary | null) => void;
  setNotice: (notice: NoticeState | null) => void;
  setSelectedThreadId: (threadId: string | null) => void;
  setThreadGoal: (goal: ThreadGoal | null) => void;
  setThreads: Dispatch<SetStateAction<Thread[]>>;
  showArchivedThreadsRef: MutableRefObject<boolean>;
  showDemoThreads: () => void;
  switchToDemoThreads: (showConnectionNotice?: boolean) => void;
};

export function useAppConnectionEffects({
  clientRef,
  connectionAttempt,
  connectionState,
  handleNotification,
  handleServerRequest,
  isDemo,
  isDemoPreview,
  locale,
  preserveThreadsAfterConnectionLoss,
  selectedThread,
  selectedThreadId,
  serverUrl,
  setAccountStatus,
  setConnectionAttempt,
  setConnectionState,
  setConversationSummary,
  setGitRemoteDiff,
  setNotice,
  setSelectedThreadId,
  setThreadGoal,
  setThreads,
  showArchivedThreadsRef,
  showDemoThreads,
  switchToDemoThreads,
}: AppConnectionEffectsParams) {
  useEffect(() => {
    return runConnectionBootstrapEffectAction({
      createClient: (onConnectionLost) =>
        new AppServerClient(
          serverUrl,
          handleNotification,
          onConnectionLost,
          handleServerRequest,
        ),
      currentClient: () => clientRef.current,
      isDemoPreview,
      preserveThreadsAfterConnectionLoss,
      setAccountStatus,
      setClient: (client) => {
        clientRef.current = client;
      },
      setConnectionState,
      setNotice,
      setSelectedThreadId,
      setThreads,
      showArchivedThreads: showArchivedThreadsRef.current,
      showDemoThreads,
      switchToDemoThreads,
    });
  }, [
    connectionAttempt,
    handleNotification,
    handleServerRequest,
    isDemoPreview,
    preserveThreadsAfterConnectionLoss,
    serverUrl,
    switchToDemoThreads,
  ]);

  useEffect(() => {
    if (connectionState !== "disconnected") {
      return undefined;
    }

    return scheduleReconnectAction({
      clearTimeout: (timeoutId) => window.clearTimeout(timeoutId),
      client: clientRef.current,
      setConnectionAttempt,
      setConnectionState,
      setTimeout: (handler, timeout) => window.setTimeout(handler, timeout),
    });
  }, [clientRef, connectionState, setConnectionAttempt, setConnectionState]);

  useEffect(() => {
    localizeDemoThreadsAction({
      connectionState,
      locale,
      setThreads,
    });
  }, [connectionState, locale, setThreads]);

  useEffect(() => {
    syncDemoInspectorStateAction({
      isDemo,
      locale,
      selectedThread,
      selectedThreadId,
      setAccountStatus,
      setConversationSummary,
      setGitRemoteDiff,
      setThreadGoal,
    });
  }, [
    isDemo,
    locale,
    selectedThread,
    selectedThreadId,
    setAccountStatus,
    setConversationSummary,
    setGitRemoteDiff,
    setThreadGoal,
  ]);
}

